  endLine?: number;
  limit?: number;
  // search only. content (default): match chunk CONTENTS, case-insensitive. path: match file PATHS/names (locate a file); with a repo this is a case-sensitive substring match (the query is also tried lowercased) scoped to one ref.
  mode?: "content" | "path";
